import requests

def get_url_content(url, headers=None, decoded=True):
    response = requests.get(url, headers=headers)
    if decoded:
        response.encoding = response.apparent_encoding
        return response.text
    else:
        return response.content

from random import choice

class ExprOp:
    def __init__(self, op, func):
        self.op = op
        self.func = func

    def __call__(self, *args, **kwargs):
        return self.func(*args, **kwargs)

    def __repr__(self):
        return f"ExprOp('{self.op}')"

class ExprNode:
    def __init__(self, value, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right

    def __repr__(self):
        return f'{self.value}'

    def evaluate(self):
        if self.left is None and self.right is None:
            return self.value
        else:
            return self.value(self.left.evaluate(), self.right.evaluate())

def random_expr(depth, vlist, ops):
    if depth == 1:
        return ExprNode(choice(vlist))
    else:
        op = choice(ops)
        return ExprNode(op, random_expr(depth-1, vlist, ops), random_expr(depth-1, vlist, ops))

import psycopg2

def db_create(dbname, template=None):
    conn = psycopg2.connect("dbname=postgres user=postgres password=password host=127.0.0.1 port=5432")
    cur = conn.cursor()
    if template:
        cur.execute(f"CREATE DATABASE {dbname} TEMPLATE {template};")
    else:
        cur.execute(f"CREATE DATABASE {dbname};")
    cur.close()
    conn.close()

import requests
import os

def download(url, file):
    try:
        with open(file, 'wb') as f:
            response = requests.get(url, stream=True)
            if response.status_code == 200:
                for chunk in response.iter_content(1024):
                    f.write(chunk)
        print("Download Completed!")
    except KeyboardInterrupt:
        os.remove(file)
        print('\nDownload aborted and the partial file is removed!')

